def get_full_prompt(screen_key: str) -> str:
    specific = SCREENS_PROMPTS.get(screen_key, "")
    return f"{GLOBAL_STYLE_BLOCK}\n\n{specific}"

if __name__ == "__main__":
    print(f"Total defined screens: {len(SCREENS_PROMPTS)}")
    for key in sorted(SCREENS_PROMPTS.keys()):
        print(f" - {key}: {len(get_full_prompt(key))} chars")
